// =============================================================
// ゲーム登録所（レジストリ）
// =============================================================
// 新しいゲームはこの配列に1エントリ追記するだけで追加できる。
// 手順は docs/ADDING_A_GAME.md を参照。
//
// ルール:
//   - 追記専用（並べ替え・削除はしない）
//   - id と no は一度リリースしたら変更しない（保存データのキー）
//   - 公開をやめるときは削除せず status: 'retired' にする
// =============================================================
import type { GameMeta } from '../game-api/types';
import { getDoc } from '../platform/storage';

